def summary_input(frame, field):
    measured = frame.copy()
    measured[field] = pd.to_numeric(measured[field], errors="coerce").replace([np.inf, -np.inf], np.nan)
    return measured


def summarise(frame):
    frame = summary_input(frame, Y_FIELD)
    keys = [X_FIELD] + ([GROUP] if GROUP is not None else [])
    # sort=False keeps the file's category order instead of an alphabetical one.
    grouped = frame.groupby(keys, as_index=False, sort=False)[Y_FIELD]
    summary = grouped.mean()
    return summary


def locked_appearance(names):
    # A shared lock keeps a model the same colour in figure 1 and figure 7.
    if PALETTE_LOCK is None:
        return None
    try:
        from graphunslopify.lockfile import appearance
    except ImportError:
        print("graphunslopify is not installed, so palette_lock was ignored")
        return None
    return appearance(PALETTE_LOCK, [str(n) for n in names])


def series_names(frame):
    if GROUP is None:
        return [None]
    if SERIES_ORDER is not None:
        return [n for n in SERIES_ORDER if n in set(frame[GROUP])] or list(SERIES_ORDER)
    return sorted(frame[GROUP].dropna().unique().tolist(), key=str)


def series_style(name, index, total):
    locked = LOCKED.get(str(name)) if LOCKED else None
    colour = locked["colour"] if locked else PALETTE[index % len(PALETTE)]
    # Colour alone is not enough in greyscale, so add a second channel.
    if total <= SECOND_CHANNEL_THRESHOLD:
        channel = ""
    elif EMPHASIS is None:
        channel = HATCHES[index % len(HATCHES)]
    else:
        # The emphasised series keeps the plain form, so the others must skip
        # it. Without this, series zero is also plain and the two collide.
        rest = HATCHES[1:] or HATCHES
        channel = rest[index % len(rest)]
    if locked and total > SECOND_CHANNEL_THRESHOLD:
        channel = locked["hatch"]
    if name == EMPHASIS:
        channel = ""
    if EMPHASIS is None:
        style = {"colour": colour, "width": 1.4, "alpha": 1.0, "zorder": 2}
    elif name == EMPHASIS:
        style = {"colour": colour, "width": 2.2, "alpha": 1.0, "zorder": 3}
    else:
        style = {"colour": colour, "width": 1, "alpha": RECEDED_ALPHA, "zorder": 1}
    style["hatch"] = channel
    return style


def category_order(frame):
    if CATEGORY_ORDER is not None:
        return [c for c in CATEGORY_ORDER if c in set(frame[X_FIELD])]
    return list(dict.fromkeys(frame[X_FIELD].tolist()))


def draw_panel(ax, df):
    frame = summarise(df)
    categories = category_order(frame)
    positions = np.arange(len(categories))
    names = series_names(frame)
    width = 0.8 / max(len(names), 1)
    for index, name in enumerate(names):
        block = frame[frame[GROUP] == name].set_index(X_FIELD).reindex(categories)
        offset = (index - (len(names) - 1) / 2) * width
        style = series_style(name, index, len(names))
        ax.bar(
            positions + offset,
            block[Y_FIELD].to_numpy(dtype=float),
            width,
            label=str(name),
            color=style["colour"],
            alpha=style["alpha"],
            zorder=style["zorder"],
            hatch=style["hatch"],
            edgecolor="white",
            linewidth=0.0,


        )
    ax.set_xticks(positions)
    ax.set_xticklabels([str(value) for value in categories])


def fit_category_labels(fig, axes):
    for rotation in (45, 90):
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        crowded = []
        for ax in axes:
            if not ax.get_visible():
                continue
            low, high = sorted(ax.get_xlim())
            labels = [label for label in ax.get_xticklabels()
                      if label.get_visible() and label.get_text().strip()
                      and low <= label.get_position()[0] <= high]
            boxes = sorted([label.get_window_extent(renderer) for label in labels], key=lambda box: box.x0)
            if any(left.overlaps(right) for left, right in zip(boxes, boxes[1:])):
                crowded.append(labels)
        if not crowded:
            return
        for labels in crowded:
            for label in labels:
                label.set_rotation(rotation)
                label.set_horizontalalignment("right" if rotation == 45 else "center")
                label.set_verticalalignment("top")
                label.set_rotation_mode("default")
        fig.tight_layout()


